<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$token=preg_replace('/[^a-f0-9]/','',strtolower((string)($_GET['token']??'')));$s=$db->prepare('SELECT p.*,l.name client_name,l.company,l.email,l.phone FROM proposals p JOIN leads l ON l.id=p.lead_id WHERE p.public_token=? LIMIT 1');$s->execute([$token]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Proposal not found.');}$s=$db->prepare('SELECT * FROM proposal_items WHERE proposal_id=? ORDER BY sort_order,id');$s->execute([$p['id']]);$items=$s->fetchAll();if($p['status']==='sent'){$db->prepare("UPDATE proposals SET status='viewed',viewed_at=NOW() WHERE id=?")->execute([$p['id']]);$db->prepare("INSERT INTO proposal_events(proposal_id,event_type,ip_address,user_agent) VALUES(?,?,?,?)")->execute([$p['id'],'viewed',$_SERVER['REMOTE_ADDR']??null,substr($_SERVER['HTTP_USER_AGENT']??'',0,500)]);}$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='accept'&&in_array($p['status'],['sent','viewed'],true)){$db->prepare("UPDATE proposals SET status='accepted',accepted_at=NOW() WHERE id=?")->execute([$p['id']]);$db->prepare("INSERT INTO proposal_events(proposal_id,event_type,ip_address,user_agent) VALUES(?,?,?,?)")->execute([$p['id'],'accepted',$_SERVER['REMOTE_ADDR']??null,substr($_SERVER['HTTP_USER_AGENT']??'',0,500)]);$db->prepare("INSERT INTO lead_activities (lead_id,activity_type,subject,description) VALUES (?,?,?,?)")->execute([$p['lead_id'],'proposal','Proposal accepted',$p['proposal_number'].' was accepted by the client.']);$p['status']='accepted';}elseif(($_POST['action']??'')==='reject'&&in_array($p['status'],['sent','viewed'],true)){$db->prepare("UPDATE proposals SET status='rejected',rejected_at=NOW() WHERE id=?")->execute([$p['id']]);$db->prepare("INSERT INTO proposal_events(proposal_id,event_type,ip_address,user_agent) VALUES(?,?,?,?)")->execute([$p['id'],'rejected',$_SERVER['REMOTE_ADDR']??null,substr($_SERVER['HTTP_USER_AGENT']??'',0,500)]);$db->prepare("INSERT INTO lead_activities (lead_id,activity_type,subject,description) VALUES (?,?,?,?)")->execute([$p['lead_id'],'proposal','Proposal rejected',$p['proposal_number'].' was rejected by the client.']);$p['status']='rejected';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$esc($p['proposal_number'])?> — Distinguished Web Services</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f6f8}.sheet{max-width:900px;margin:40px auto;background:#fff;padding:55px;box-shadow:0 8px 30px #00000012}</style></head><body><main class="sheet"><div class="d-flex justify-content-between"><div><h1 class="h2">Distinguished Web Services</h1><p class="text-muted">Proposal & Quotation</p></div><div class="text-end"><strong><?=$esc($p['proposal_number'])?></strong><br><small>Valid until <?=$esc($p['valid_until']?:'—')?></small></div></div><hr><h2><?=$esc($p['title'])?></h2><p>Prepared for <strong><?=$esc($p['client_name'])?></strong><?php if($p['company']):?> — <?=$esc($p['company'])?><?php endif;?></p><div class="table-responsive"><table class="table"><thead><tr><th>Description</th><th class="text-end">Qty</th><th class="text-end">Unit</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=$esc($i['description'])?></td><td class="text-end"><?=$esc($i['quantity'])?></td><td class="text-end"><?=$esc($p['currency'])?> <?=number_format((float)$i['unit_price'],2)?></td><td class="text-end"><?=$esc($p['currency'])?> <?=number_format((float)$i['amount'],2)?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="3" class="text-end">Subtotal</th><th class="text-end"><?=$esc($p['currency'])?> <?=number_format((float)$p['subtotal'],2)?></th></tr><tr><td colspan="3" class="text-end">Discount</td><td class="text-end">- <?=$esc($p['currency'])?> <?=number_format((float)$p['discount'],2)?></td></tr><tr><td colspan="3" class="text-end">Tax</td><td class="text-end"><?=$esc($p['currency'])?> <?=number_format((float)$p['tax'],2)?></td></tr><tr class="table-dark"><th colspan="3" class="text-end">Total</th><th class="text-end"><?=$esc($p['currency'])?> <?=number_format((float)$p['total'],2)?></th></tr></tfoot></table></div><?php if($p['notes']):?><h3 class="h6 mt-4">Notes</h3><p><?=nl2br($esc($p['notes']))?></p><?php endif;?><?php if($p['terms']):?><h3 class="h6 mt-4">Terms</h3><p><?=nl2br($esc($p['terms']))?></p><?php endif;?><?php if(in_array($p['status'],['sent','viewed'],true)):?><div class="d-flex gap-2 mt-4"><form method="post"><input type="hidden" name="action" value="accept"><button class="btn btn-dark">Accept Proposal</button></form><form method="post"><input type="hidden" name="action" value="reject"><button class="btn btn-outline-danger">Reject</button></form></div><?php else:?><div class="alert alert-secondary mt-4">Proposal status: <strong><?=ucfirst($esc($p['status']))?></strong></div><?php endif;?></main></body></html>